def __init__(self, text=None, entities=None):
    if entities is None:
        entities = []
    if text is None:
        text = ""

    self.text = text
    self.entities = entities
    self._slot_value = None  # HACK used by slot to prevent code duplication

def get_current_file_information(self):
    if self._current_file is None:
        return (None, None)
    return (self._current_file.name, self._current_file.line_nb)
